"use client";

import { FlowDiagram } from "@diax/react";
import {
  CheckCircle2,
  Clock,
  Code,
  Container,
  GitMerge,
  Loader2,
  Rocket,
  type LucideIcon,
} from "lucide-react";

interface StatusNodeProps {
  icon: LucideIcon;
  title: string;
  status: "success" | "running" | "pending";
  desc: string;
  time: string;
  branch: string;
}

// Linear-style advanced pipeline node
const StatusNode = ({ icon: Icon, title, status, desc, time, branch }: StatusNodeProps) => {
  const isRunning = status === "running";
  const isSuccess = status === "success";

  return (
    <div
      className={`group flex flex-col justify-between rounded-xl border p-4 shadow-xl backdrop-blur-md transition-all duration-300 min-w-[260px] bg-black/60 hover:scale-[1.02] ${
        isRunning
          ? "border-[#5E6AD2]/50 shadow-[#5E6AD2]/10"
          : isSuccess
            ? "border-emerald-500/30"
            : "border-white/10"
      }`}
    >
      <div className="flex items-start justify-between mb-3 w-full">
        <div className="flex items-center gap-3">
          <div
            className={`flex h-10 w-10 items-center justify-center rounded-lg border ${
              isRunning
                ? "bg-[#5E6AD2]/20 text-[#5E6AD2] border-[#5E6AD2]/50 shadow-[0_0_15px_rgba(94,106,210,0.4)]"
                : isSuccess
                  ? "bg-emerald-500/20 text-emerald-400 border-emerald-500/30"
                  : "bg-white/5 text-white/40 border-white/10"
            }`}
          >
            {isRunning ? (
              <Loader2 className="h-5 w-5 animate-spin" />
            ) : (
              <Icon className="h-5 w-5" />
            )}
          </div>
          <div className="flex flex-col">
            <h4
              className={`text-sm font-semibold tracking-wide ${
                isRunning ? "text-white" : isSuccess ? "text-white/90" : "text-white/50"
              }`}
            >
              {title}
            </h4>
            <span className="text-[11px] font-mono tracking-widest text-[#5E6AD2] opacity-80 mt-0.5 uppercase">
              {desc}
            </span>
          </div>
        </div>

        <div className="flex items-center">
          {isSuccess && (
            <CheckCircle2 className="h-5 w-5 text-emerald-400 drop-shadow-[0_0_8px_rgba(52,211,153,0.5)]" />
          )}
        </div>
      </div>

      {/* Branch & Time Metadata */}
      <div className="flex items-center justify-between border-t border-white/5 pt-3 mt-1">
        <div className="flex items-center gap-1.5 px-2 py-0.5 rounded bg-white/5 text-[10px] text-white/60 font-mono">
          <GitMerge className="h-3 w-3" />
          {branch}
        </div>
        {time && (
          <div className="flex items-center gap-1 text-[10px] text-white/40 font-mono">
            <Clock className="h-3 w-3" />
            {time}
          </div>
        )}
      </div>

      {/* Running Progress Bar */}
      {isRunning && (
        <div className="absolute bottom-0 left-0 h-[2px] w-full bg-[#5E6AD2]/20 overflow-hidden rounded-b-xl">
          <div className="h-full bg-[#5E6AD2] w-1/2 rounded-r-full shadow-[0_0_10px_#5E6AD2] animate-[pulse_2s_ease-in-out_infinite]"></div>
        </div>
      )}
    </div>
  );
};

export default function CIPipeline() {
  return (
    <div className="w-full h-full min-h-[500px] bg-[#0A0A0A] flex items-center justify-center p-12 rounded-xl relative overflow-hidden">
      {/* Sci-Fi Grid lines */}
      <div className="absolute inset-0 bg-[linear-gradient(rgba(255,255,255,0.03)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,0.03)_1px,transparent_1px)] bg-[size:40px_40px] [mask-image:radial-gradient(ellipse_60%_60%_at_50%_50%,#000_20%,transparent_100%)]"></div>

      <FlowDiagram
        nodes={[
          {
            id: "push",
            content: (
              <StatusNode
                icon={GitMerge}
                title="Version Bump"
                desc="Commit push"
                status="success"
                branch="main"
                time="2m ago"
              />
            ),
          },
          {
            id: "lint",
            content: (
              <StatusNode
                icon={Code}
                title="Static Analysis"
                desc="SonarQube / Jest"
                status="success"
                branch="main"
                time="1m 30s"
              />
            ),
          },
          {
            id: "build",
            content: (
              <StatusNode
                icon={Container}
                title="Dockerize"
                desc="Build artifacts"
                status="running"
                branch="main"
                time="Running..."
              />
            ),
          },
          {
            id: "deploy",
            content: (
              <StatusNode
                icon={Rocket}
                title="Prod Rollout"
                desc="Kubernetes Helm"
                status="pending"
                branch="main"
                time="Pending"
              />
            ),
          },
        ]}
        relations={[
          "push->lint",
          "lint->build",
          "build->deploy", // Pending step
        ]}
        direction="horizontal"
        centered
        density="spacious"
      />
    </div>
  );
}
